<?php
namespace Andmarruda\Lpb\Widgets;

use Illuminate\Support\Str;

/**
 * TypeScript types of widget configs as renderers receive them in delivery
 * payloads: media references are resolved to LpbMedia (or null).
 */
final class TypeScriptGenerator
{
    public function __construct(private WidgetRegistry $widgets)
    {
    }

    public function generate(): string
    {
        $lines = [
            '// Generated by php artisan lpb:types. Do not edit.',
            '',
            'export interface LpbMedia {',
            '  id: string | number;',
            '  url: string;',
            '  mime_type: string;',
            '  meta: Record<string, unknown>;',
            '}',
            '',
            'export interface LpbLink {',
            '  url: string;',
            "  target?: '_self' | '_blank';",
            '  label?: string;',
            '}',
            '',
        ];

        $map = [];
        foreach ($this->widgets->all() as $name => $definition) {
            $interface = Str::studly(str_replace('.', '-', $name)) . 'Config';
            $lines[] = "/** {$name}, schema version {$definition->version} */";
            $lines[] = "export interface {$interface} " . $this->type($this->widgets->schema($name), 0);
            $lines[] = '';
            $map[] = '  ' . json_encode($name) . ": {$interface};";
        }

        $lines[] = 'export interface LpbWidgetConfigs {';
        array_push($lines, ...$map);
        $lines[] = '}';

        return implode("\n", $lines) . "\n";
    }

    /**
     * @param array $schema
     * @param int $depth
     * @return string
     */
    private function type(array $schema, int $depth): string
    {
        $kind = $schema['x-lpb-type'] ?? null;
        if ($kind === 'media') {
            return 'LpbMedia | null';
        }
        if ($kind === 'link') {
            return 'LpbLink';
        }
        if (isset($schema['enum'])) {
            return implode(' | ', array_map(fn ($value) => json_encode($value), $schema['enum'])) ?: 'never';
        }

        $types = (array) ($schema['type'] ?? []);
        if ($types === [] && isset($schema['properties'])) {
            $types = ['object'];
        }

        $mapped = array_map(fn (string $type) => match ($type) {
            'string' => 'string',
            'integer', 'number' => 'number',
            'boolean' => 'boolean',
            'null' => 'null',
            'array' => $this->arrayType($schema, $depth),
            'object' => $this->objectType($schema, $depth),
            default => 'unknown',
        }, $types);

        return $mapped === [] ? 'unknown' : implode(' | ', array_unique($mapped));
    }

    private function arrayType(array $schema, int $depth): string
    {
        $item = isset($schema['items']) && is_array($schema['items']) ? $this->type($schema['items'], $depth) : 'unknown';
        return str_contains($item, ' ') && !str_starts_with($item, '{') ? "Array<{$item}>" : "{$item}[]";
    }

    private function objectType(array $schema, int $depth): string
    {
        $properties = (array) ($schema['properties'] ?? []);
        if ($properties === []) {
            return ($schema['additionalProperties'] ?? true) === false ? 'Record<string, never>' : 'Record<string, unknown>';
        }

        $required = (array) ($schema['required'] ?? []);
        $indent = str_repeat('  ', $depth + 1);
        $lines = ['{'];
        foreach ($properties as $name => $property) {
            $doc = $property['description'] ?? $property['title'] ?? null;
            if (is_string($doc)) {
                $lines[] = "{$indent}/** " . str_replace('*/', '* /', $doc) . ' */';
            }
            $key = preg_match('/^[A-Za-z_$][A-Za-z0-9_$]*$/', $name) ? $name : json_encode($name);
            $optional = in_array($name, $required, true) ? '' : '?';
            $lines[] = "{$indent}{$key}{$optional}: " . $this->type((array) $property, $depth + 1) . ';';
        }
        $lines[] = str_repeat('  ', $depth) . '}';
        return implode("\n", $lines);
    }
}
